import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{Br as i,Fr as a,Hr as o,Ir as s,Lr as c,Pr as l,Rr as u,Ur as d,Vr as f,Wr as p,zr as m}from"./chunks/assets.DAjhvrpn.js";var h=JSON.parse(`{"title":"Air supply","description":"","frontmatter":{"title":"Air supply","lang":"en-US"},"headers":[],"relativePath":"building/air-supply.md","filePath":"building/air-supply.md"}`),g={name:`building/air-supply.md`};function _(n,h,g,_,v,y){return e(),r(`div`,null,[...h[0]||=[t(`<h1 id="air-supply" tabindex="-1">Air supply <a class="header-anchor" href="#air-supply" aria-label="Permalink to “Air supply”">​</a></h1><p>The air supply module consists of a manifold connected to the main lab air supply and an air flow control valve on the manifold whose output goes to an air flowmeter. The flowmeter provides a constant flow of air, through an adapter in the cabinet panel, to the cup that makes the Styrofoam ball float. The manifold also supplies air to other modules, such as the air puffs, and another manifold can be added if other modules require an air supply.</p><figure><img src="`+p+`" alt="Air supply module." width="1280" height="932" loading="lazy"><figcaption>Air supply module.</figcaption></figure><h2 id="manifold-assembly" tabindex="-1">Manifold assembly <a class="header-anchor" href="#manifold-assembly" aria-label="Permalink to “Manifold assembly”">​</a></h2><p>If the air puffs are going to be used, we recommend adding the pressure gauge during this step; otherwise, put a plug instead of the gauge on the second outlet of the manifold. First, install a 1/2 NPT plug and a push-to-connect straight adapter for air, for 3/8&quot; tube OD x 1/2 NPT male, in the manifold. Then install the pressure gauge, or another plug if the air puffs are not going to be installed. Finally, install a 3/8 NPT male inlet x 3/8&quot; push-to-connect female outlet air flow control valve into the first outlet of the manifold.</p><figure><img src="`+d+`" alt="" width="1280" height="932" loading="lazy"></figure><p>Once assembled, place the manifold in the lower T-slotted profile at the left side of the cabinet (the same as the DIN rails). First, insert a pair of T-slotted framing drop-in nuts with spring tab, 5/16&quot;-18 thread size, into the profile. Then, place a pair of 10-24 square nuts at the back of the 3D printed frame-to-manifold adapter and screw the adapter to the frame with 5/16&quot;-18 x 1/2&quot; long low-profile screws.</p><p>Attach the manifold to the adapter using a pair of 10-24 x 1-7/8&quot; long screws.</p><figure><img src="`+o+`" alt="" width="1280" height="932" loading="lazy"></figure><h2 id="air-flowmeter-assembly" tabindex="-1">Air flowmeter assembly <a class="header-anchor" href="#air-flowmeter-assembly" aria-label="Permalink to “Air flowmeter assembly”">​</a></h2><p>To assemble the air flowmeter, first attach a push-to-connect 90 degree swivel elbow for air, for 1/4&quot; tube OD x 1/4 NPT male, to the top outlet, and a push-to-connect 90 degree swivel elbow for air, for 3/8&quot; tube OD x 1/4 NPT male, to the bottom inlet. Then, use a couple of 10-32 x 5/16&quot; long screws to attach the air-flowmeter-to-DIN-mounting-clip adapter to the air flowmeter. Finally, use number 8 x 5/16&quot; long rounded head thread-forming screws to attach a spring clip DIN rail mounting adapter.</p><figure><img src="`+f+`" alt="" width="1280" height="932" loading="lazy"></figure><p>Attach the air flowmeter to the DIN rail by hooking in the bottom part first, then pushing it up and forward at the same time.</p><figure><img src="`+i+`" alt="" width="1280" height="932" loading="lazy"></figure><p>Then, insert one end of a firm polyurethane air tube, 1/4&quot; ID, 3/8&quot; OD, into the inlet of the air flowmeter until it clicks and the tube can&#39;t come out of the connector. Measure the distance to the outlet connector of the air flow control valve (bottom of the connector, as seen in the pictures below), cut the tube and connect it.</p><figure><img src="`+m+`" alt="" width="1280" height="932" loading="lazy"></figure><figure><img src="`+u+`" alt="" width="1280" height="932" loading="lazy"></figure><h2 id="air-flow-adapter" tabindex="-1">Air flow adapter <a class="header-anchor" href="#air-flow-adapter" aria-label="Permalink to “Air flow adapter”">​</a></h2><p>To install the air flow adapter, first screw the push-to-connect through-wall adapter, 1/4&quot; tube OD x 1/4 NPT female, into the cabinet hole. Then, from inside the cabinet, screw the 1/4 NPT male air nozzle into the adapter, fit the air-supply-to-ball-adapter panel gasket and the 3D printed hose-to-panel adapter over it, and attach them to the panel with four 1/4&quot;-20 x 3/4&quot; long screws and four 1/4&quot;-20 locknuts. Follow the same procedure as above to connect a firm polyurethane air tube, 1/8&quot; ID, 1/4&quot; OD, from the flowmeter outlet to the cabinet inlet.</p><figure><img src="`+c+`" alt="" width="1280" height="932" loading="lazy"></figure><figure><img src="`+s+`" alt="" width="1280" height="932" loading="lazy"></figure><figure><img src="`+a+`" alt="" width="1280" height="932" loading="lazy"></figure><figure><img src="`+l+`" alt="" width="1280" height="932" loading="lazy"></figure><p>Take a very flexible PVC duct hose, 1 1/4&quot; ID, 1 1/2&quot; OD, attach a PVC screw-on fitting for 1 1/4&quot; ID to one end and connect it to the adapter in the cabinet. Pull the stage all the way out, measure the length of hose needed, cut it and attach a fitting to the other end. Finally, connect it to the cup on the stage.</p>`,24)]])}var v=n(g,[[`render`,_]]);export{h as __pageData,v as default};